// AUDIT8_SALT (0 = the committed seeds). Do not edit; not part of the suite.
//! Recovery accepted a superblock that existed only in the page cache and
//! never made it durable (K-01). Volume creation publishes superblock A, then
//! B, as its commit point. When A's fdatasync fails, or the process dies
//! between A's write and its sync, `create_volume` reports an error (or never
//! returns), yet A stays CRC-valid in the page cache: a retried create refuses
//! the root ("volume superblock already present"), recovery accepts it, the
//! writer acknowledges FUA and FLUSH, and the next power loss removes the only
//! superblock copy. The acknowledged data is then unreachable ("no valid
//! superblock"). A creation that dies after A is durable but before B is
//! written leaves a single copy, which nothing ever completed.
//!
//! Writable recovery must make both copies of the superblock it selected
//! durable before any other repair and before the writer resumes, preserving
//! a valid copy first so that an interruption at any point never destroys the
//! copy a later recovery needs; read-only inspection must not write at all.

use std::io;
use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};
use std::sync::{Arc, Mutex};

use rand::rngs::StdRng;
use rand::SeedableRng;
use uuid::Uuid;

use maki_backing::Backing;
use maki_core::volume::{Volume, VolumeOptions};
use maki_format::ab::AbStore;
use maki_format::error::FormatError;
use maki_format::geometry::Geometry;
use maki_format::init;
use maki_format::layout;
use maki_format::superblock::{load_volume_superblock, Superblock, VolumeSuperblock};
use maki_test_support::crash_backing::FaultOp;
use maki_test_support::CrashableBacking;

const CT: usize = 544;

fn superblock() -> Superblock {
    Superblock {
        generation: 0,
        volume_uuid: Uuid::from_u128(0x5B_D0AB),
        provider_type: "fake".into(),
        crypto_compatibility_id: "test-profile-v1".into(),
        key_identity: "k".into(),
        geometry: Geometry::compute(512, 512, 512, CT as u32, 512 * 64, 512 * 16).unwrap(),
        format_version: 1,
        created_unix: 0,
    }
}

fn options() -> VolumeOptions {
    VolumeOptions {
        journal_segment_size: 64 * 1024,
    }
}

fn create(backing: &CrashableBacking, discard: bool) -> Result<Superblock, FormatError> {
    if discard {
        init::create_volume_with_discard(backing, superblock())
    } else {
        init::create_volume(backing, superblock())
    }
}

fn recover(backing: &Arc<CrashableBacking>) -> Result<Volume, String> {
    Volume::recover(backing.clone() as Arc<dyn Backing>, options()).map_err(|e| e.to_string())
}

/// The process dies at operation `cut`: it and every later operation fail.
fn die_at(backing: &CrashableBacking, cut: usize) {
    let seen = Arc::new(AtomicUsize::new(0));
    backing.set_fault_hook(Some(Arc::new(move |_op: &FaultOp<'_>| {
        (seen.fetch_add(1, Ordering::SeqCst) >= cut).then(|| io::Error::other("process died"))
    })));
}

/// The number of backing operations `run` performs.
fn operations(backing: &CrashableBacking, run: impl FnOnce()) -> usize {
    let seen = Arc::new(AtomicUsize::new(0));
    let counter = seen.clone();
    backing.set_fault_hook(Some(Arc::new(move |_op: &FaultOp<'_>| {
        counter.fetch_add(1, Ordering::SeqCst);
        None
    })));
    run();
    backing.set_fault_hook(None);
    seen.load(Ordering::SeqCst)
}

/// Fail (writeback EIO) the first operation `fails` selects; CrashableBacking
/// models Linux, so a failed sync leaves its writes readable but volatile and
/// a plain retry of the sync would not persist them.
fn fail_once(
    backing: &CrashableBacking,
    fails: impl Fn(&FaultOp<'_>) -> bool + Send + Sync + 'static,
) -> Arc<AtomicBool> {
    let fired = Arc::new(AtomicBool::new(false));
    let flag = fired.clone();
    backing.set_fault_hook(Some(Arc::new(move |op: &FaultOp<'_>| {
        (fails(op) && !flag.swap(true, Ordering::SeqCst)).then(|| io::Error::other("EIO"))
    })));
    fired
}

fn superblock_sides(backing: &CrashableBacking) -> (Option<u64>, Option<u64>) {
    AbStore::new(layout::SUPERBLOCK_A, layout::SUPERBLOCK_B)
        .side_generations::<VolumeSuperblock>(backing)
        .unwrap()
}

fn read_file(backing: &CrashableBacking, path: &str) -> Option<Vec<u8>> {
    let file = match backing.open(path, false) {
        Ok(file) => file,
        Err(error) if error.kind() == io::ErrorKind::NotFound => return None,
        Err(error) => panic!("{path}: {error}"),
    };
    let mut bytes = vec![0; file.len().unwrap() as usize];
    file.read_at(0, &mut bytes).unwrap();
    Some(bytes)
}

/// Recover, acknowledge a FUA write and a FLUSHed write, lose power: both
/// superblock copies must have been durable, and the data readable.
fn acknowledged_writes_survive_power_loss(backing: &Arc<CrashableBacking>, context: &str) {
    let mut volume = recover(backing).unwrap_or_else(|e| {
        panic!("{context}: recovery refused a root with a valid superblock: {e}")
    });
    volume
        .write_ct(3, &[0x5A; CT], true)
        .expect("FUA write acknowledged");
    volume
        .write_ct(4, &[0x6B; CT], false)
        .expect("write accepted");
    volume.flush().expect("FLUSH acknowledged");
    drop(volume);

    backing.crash_all_lost();
    let sides = superblock_sides(backing);
    assert!(
        sides.0.is_some() && sides.1.is_some(),
        "{context}: recovery resumed the writer without both superblock copies durable \
         (after the power loss: {sides:?})"
    );
    let volume = recover(backing).unwrap_or_else(|e| {
        panic!(
            "{context}: FLUSH/FUA-acknowledged data is unreachable after a power loss: recovery \
             accepted a page-cache-only superblock without making it durable; now: {e}"
        )
    });
    assert_eq!(
        volume.read_ct(3).unwrap().map(|(_, ct)| ct),
        Some(vec![0x5A; CT]),
        "{context}: acknowledged FUA write lost"
    );
    assert_eq!(
        volume.read_ct(4).unwrap().map(|(_, ct)| ct),
        Some(vec![0x6B; CT]),
        "{context}: FLUSH-acknowledged write lost"
    );
}

type Selector = Box<dyn Fn(&FaultOp<'_>) -> bool + Send + Sync>;

/// One failed operation of the superblock publication, by name.
fn publication_failures() -> Vec<(&'static str, Selector)> {
    let is_sync = |want: &'static str| -> Selector {
        Box::new(move |op| matches!(op, FaultOp::SyncData { path } if *path == want))
    };
    // The first root sync after superblock.b's data sync publishes its dirent.
    let b_synced = Arc::new(AtomicBool::new(false));
    let root_after_b: Selector = Box::new(move |op| match op {
        FaultOp::SyncData { path } if *path == layout::SUPERBLOCK_B => {
            b_synced.store(true, Ordering::SeqCst);
            false
        }
        FaultOp::SyncDir { dir } => dir.is_empty() && b_synced.load(Ordering::SeqCst),
        _ => false,
    });
    vec![
        ("the superblock.a data sync", is_sync(layout::SUPERBLOCK_A)),
        ("the superblock.b data sync", is_sync(layout::SUPERBLOCK_B)),
        ("the root sync publishing superblock.b", root_after_b),
    ]
}

#[test]
fn a_failed_superblock_publication_at_create_is_made_durable_by_recovery() {
    for discard in [false, true] {
        for (name, fails) in publication_failures() {
            let context = format!("discard {discard}, {name} failed");
            let backing = Arc::new(CrashableBacking::new());
            let fired = fail_once(&backing, fails);
            assert!(create(&backing, discard).is_err(), "{context}: reported");
            assert!(fired.load(Ordering::SeqCst), "{context}: the fault fired");
            backing.set_fault_hook(None);

            // Same boot: the operator retries and is told the root is a volume.
            match create(&backing, discard) {
                Err(FormatError::AlreadyExists(_)) => {}
                other => panic!("{context}: retried create: {other:?}"),
            }
            acknowledged_writes_survive_power_loss(&backing, &context);
        }
    }
}

#[test]
fn recovery_completes_a_creation_killed_at_any_point() {
    for discard in [false, true] {
        let total = {
            let backing = CrashableBacking::new();
            operations(&backing, || {
                create(&backing, discard).unwrap();
            })
        };
        assert!(total > 10, "the sweep must see the whole creation");
        let mut published = 0;
        for cut in 0..total {
            let context = format!("discard {discard}, killed at operation {cut}/{total}");
            let backing = Arc::new(CrashableBacking::new());
            die_at(&backing, cut);
            assert!(create(&backing, discard).is_err(), "{context}");
            // The process restarts: the page cache survives.
            backing.set_fault_hook(None);
            if load_volume_superblock(backing.as_ref()).is_err() {
                // Not a volume yet; `review_init_crash` covers this side.
                continue;
            }
            published += 1;
            acknowledged_writes_survive_power_loss(&backing, &context);
        }
        assert!(published > 0, "some cut must leave a published superblock");
    }
}

/// The states a failed creation leaves the two copies in.
#[derive(Clone, Copy, Debug, PartialEq)]
enum Interrupted {
    /// superblock.a's sync failed: one copy, readable but never durable.
    OnlyAVolatile,
    /// Killed after superblock.a was durable, before superblock.b existed.
    OnlyADurable,
    /// superblock.b's sync failed: A durable, B readable but volatile.
    BVolatile,
}

fn interrupted(kind: Interrupted) -> Arc<CrashableBacking> {
    let backing = Arc::new(CrashableBacking::new().with_tearing(512));
    match kind {
        Interrupted::OnlyAVolatile => {
            fail_once(
                &backing,
                |op| matches!(op, FaultOp::SyncData { path } if *path == layout::SUPERBLOCK_A),
            );
        }
        Interrupted::OnlyADurable => {
            let killed = Arc::new(AtomicBool::new(false));
            backing.set_fault_hook(Some(Arc::new(move |op: &FaultOp<'_>| {
                if matches!(op, FaultOp::Open { path, create: true } if *path == layout::SUPERBLOCK_B)
                {
                    killed.store(true, Ordering::SeqCst);
                }
                killed
                    .load(Ordering::SeqCst)
                    .then(|| io::Error::other("process died"))
            })));
        }
        Interrupted::BVolatile => {
            fail_once(
                &backing,
                |op| matches!(op, FaultOp::SyncData { path } if *path == layout::SUPERBLOCK_B),
            );
        }
    }
    assert!(create(&backing, false).is_err(), "{kind:?}");
    backing.set_fault_hook(None);
    let sides = superblock_sides(&backing);
    let expected = match kind {
        Interrupted::OnlyAVolatile | Interrupted::OnlyADurable => (Some(1), None),
        Interrupted::BVolatile => (Some(1), Some(2)),
    };
    assert_eq!(sides, expected, "{kind:?}: the interrupted creation");
    backing
}

/// What follows a recovery that stopped at some operation.
#[derive(Clone, Copy, Debug)]
enum Then {
    /// The process died (its unsynced writes stay dirty) and power was lost:
    /// each unsynced write is kept, lost or torn independently.
    PowerLoss(u64),
    /// The process died and power was lost in the worst way for one file:
    /// its last unsynced write keeps only its first sector, every other
    /// volatile operation is lost.
    TornLastWrite(&'static str),
    /// The operation failed with writeback EIO (its dirty writes are marked
    /// clean yet stay readable) and the process restarted.
    Restart,
}

#[test]
fn a_recovery_interrupted_while_restoring_the_superblock_never_loses_it() {
    for kind in [
        Interrupted::OnlyAVolatile,
        Interrupted::OnlyADurable,
        Interrupted::BVolatile,
    ] {
        let total = {
            let backing = interrupted(kind);
            operations(&backing, || {
                recover(&backing).unwrap();
            })
        };
        for cut in 0..=total {
            for then in [
                Then::PowerLoss(0),
                Then::PowerLoss(1),
                Then::PowerLoss(2),
                Then::TornLastWrite(layout::SUPERBLOCK_A),
                Then::TornLastWrite(layout::SUPERBLOCK_B),
                Then::Restart,
            ] {
                let context =
                    format!("{kind:?}, recovery stopped at operation {cut}/{total}, then {then:?}");
                let backing = interrupted(kind);
                backing.set_lenient_sync_failures(!matches!(then, Then::Restart));
                die_at(&backing, cut);
                let recovered = recover(&backing);
                if cut == total {
                    assert!(recovered.is_ok(), "{context}: {:?}", recovered.err());
                }
                drop(recovered);
                backing.set_fault_hook(None);
                backing.set_lenient_sync_failures(false);

                match then {
                    Then::PowerLoss(seed) => {
                        backing.crash(&mut StdRng::seed_from_u64(crate::a8_salt() ^ seed ^ ((cut as u64) << 8)))
                    }
                    Then::TornLastWrite(path) => {
                        if !backing.exists(path).unwrap() {
                            continue;
                        }
                        backing.crash_keep_torn_prefix(path, 512);
                    }
                    Then::Restart => {}
                }
                let loads = load_volume_superblock(backing.as_ref());
                if cut == total || kind != Interrupted::OnlyAVolatile {
                    assert!(
                        loads.is_ok(),
                        "{context}: no superblock survived, although one was durable before \
                         recovery or recovery completed: {:?}",
                        loads.err()
                    );
                }
                if loads.is_ok() {
                    acknowledged_writes_survive_power_loss(&backing, &context);
                }
            }
        }
    }
}

#[test]
fn repeated_recoveries_leave_both_superblock_copies_unchanged() {
    for kind in [
        None,
        Some(Interrupted::OnlyADurable),
        Some(Interrupted::BVolatile),
    ] {
        let backing = match kind {
            None => {
                let backing = Arc::new(CrashableBacking::new());
                create(&backing, false).unwrap();
                backing
            }
            Some(kind) => interrupted(kind),
        };
        drop(recover(&backing).unwrap());
        // Recovery completes what creation would have published: the same
        // superblock in both copies, A at generation 1 and B at 2.
        assert_eq!(superblock_sides(&backing), (Some(1), Some(2)), "{kind:?}");
        let first = (
            read_file(&backing, layout::SUPERBLOCK_A),
            read_file(&backing, layout::SUPERBLOCK_B),
        );
        let selected = load_volume_superblock(backing.as_ref()).unwrap();
        assert_eq!(
            selected.superblock,
            Superblock {
                generation: 2,
                ..superblock()
            },
            "{kind:?}"
        );
        for round in 0..3 {
            drop(recover(&backing).unwrap());
            assert_eq!(
                (
                    read_file(&backing, layout::SUPERBLOCK_A),
                    read_file(&backing, layout::SUPERBLOCK_B),
                ),
                first,
                "{kind:?}, recovery {round}: an idempotent recovery changed the superblock"
            );
        }
    }
}

#[test]
fn read_only_inspection_never_writes() {
    let backing = interrupted(Interrupted::OnlyAVolatile);
    let writes = Arc::new(Mutex::new(Vec::new()));
    let seen = writes.clone();
    backing.set_fault_hook(Some(Arc::new(move |op: &FaultOp<'_>| {
        if !matches!(op, FaultOp::Open { create: false, .. }) {
            seen.lock().unwrap().push(format!("{op:?}"));
        }
        None
    })));
    let dynamic = backing.clone() as Arc<dyn Backing>;
    load_volume_superblock(backing.as_ref()).unwrap();
    init::load_superblock(backing.as_ref()).unwrap();
    let superblock = maki_core::recovery::load_superblock(&dynamic).unwrap();
    maki_core::recovery::scan_journal(&dynamic, &superblock, 0, 64 * 1024).unwrap();
    assert!(maki_format::checker::check_volume(backing.as_ref())
        .unwrap()
        .ok());
    assert!(maki_core::check::deep_check(dynamic, 64 * 1024)
        .unwrap()
        .ok());
    backing.set_fault_hook(None);
    assert_eq!(
        writes.lock().unwrap().as_slice(),
        &[] as &[String],
        "read-only inspection modified the backing"
    );
}
